import 'dart:convert';
import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:move_your_body/features/ai_inference/services/tokenizer_service.dart';

/// Checks that the on-device Dart WordPiece tokenizer produces the same token
/// ids as the reference BERT tokenizer for every exercise tag and the sample
/// queries. Expected ids come from `test/fixtures/tokenizer_parity.json`,
/// generated by `notebooks/onnx_pipeline_validation.ipynb`.
void main() {
  final fixture =
      jsonDecode(File('test/fixtures/tokenizer_parity.json').readAsStringSync())
          as Map<String, dynamic>;
  final cases = (fixture['cases'] as List).cast<Map<String, dynamic>>();
  final tokenizer = TokenizerService.buildTokenizer(
    File(fixture['vocab'] as String).readAsStringSync(),
  );

  List<int> encode(String text) {
    final output = tokenizer.encode(TokenizerService.prepareText(text));
    return output.inputIds.sublist(0, output.realLength);
  }

  test('fixture covers tags and queries', () {
    expect(cases.where((c) => c['source'] == 'tag'), isNotEmpty);
    expect(cases.where((c) => c['source'] == 'query'), isNotEmpty);
  });

  test('Dart token ids match the reference tokenizer', () {
    final mismatches = <String>[
      for (final c in cases)
        if (!listEquals(
          encode(c['input'] as String),
          (c['ids'] as List).cast<int>(),
        ))
          c['input'] as String,
    ];
    expect(mismatches, isEmpty, reason: 'Token ids differ for: $mismatches');
  });

  test('snake_case tags tokenize like their natural-text form', () {
    expect(encode('lower_back_pain'), encode('lower back pain'));
  });
}
